#!/usr/bin/env python3
"""Generate RTL when generator sources, configuration or generated bytes change."""

import argparse
import os
from pathlib import Path
import re
import subprocess

from build_cache import cached_build, tool_identity

ROOT = Path(__file__).resolve().parents[1]


def repository_revision(env=None):
    """Product RTL includes this revision in its provenance banner."""
    try:
        result = subprocess.run(["git", "rev-parse", "--verify", "HEAD"], cwd=ROOT,
                                env=env, capture_output=True, text=True)
    except FileNotFoundError:
        return None
    return result.stdout.strip() if result.returncode == 0 else None


def generator_inputs():
    hdl = ROOT / "hdl"
    return sorted((hdl / "src/main").rglob("*.scala")) + [
        hdl / "build.sbt", *sorted((hdl / "project").glob("*.sbt")),
        *sorted((hdl / "project").glob("*.scala")), hdl / "project/build.properties",
        Path(__file__),
    ]


def configuration_environment(inputs, env):
    # Include every uppercase literal, rather than maintaining a second list of
    # CpuConfig's environment switches. Newly added switches invalidate correctly.
    keys = {key for path in inputs if path.suffix == ".scala"
            for key in re.findall(r'"([A-Z][A-Z0-9_]*)"', path.read_text())}
    keys.update(("JAVA_HOME", "JAVA_TOOL_OPTIONS", "JDK_JAVA_OPTIONS", "JAVA_OPTS",
                 "SBT_OPTS", "COURSIER_REPOSITORIES", "SBT"))
    return {key: env.get(key) for key in sorted(keys)}


def generate(directory, generator="ooo.Generate", env=None, *, force=False, log=None):
    directory = Path(directory).resolve()
    environment = dict(os.environ if env is None else env, RTL_OUT=str(directory))
    inputs = generator_inputs()
    sbt = environment.get("SBT", "sbt")
    java = str(Path(environment["JAVA_HOME"]) / "bin/java") if environment.get("JAVA_HOME") else "java"
    signature = {"generator": generator, "environment": configuration_environment(inputs, environment),
                 "repository_revision": repository_revision(environment),
                 "sbt": tool_identity(sbt, env=environment),
                 "java": tool_identity(java, ("-version",), env=environment)}

    def build():
        command = [sbt, "-batch", f"runMain {generator}"]
        if log is None:
            subprocess.run(command, cwd=ROOT / "hdl", env=environment, check=True)
        else:
            with Path(log).open("w") as stream:
                subprocess.run(command, cwd=ROOT / "hdl", env=environment, check=True,
                               stdout=stream, stderr=subprocess.STDOUT)
        if generator_inputs() != inputs:
            raise RuntimeError("Generator source list changed during elaboration; rerun generation")
        if repository_revision(environment) != signature["repository_revision"]:
            raise RuntimeError("Repository revision changed during elaboration; rerun generation")

    rebuilt = cached_build(directory / ".generation.json", inputs,
                           [directory / "cpu.v", directory / "configuration.json"],
                           signature, build, force=force)
    print(f"RTL {'generated' if rebuilt else 'reused'}: {directory}", flush=True)
    return rebuilt


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("directory", type=Path)
    parser.add_argument("--generator", default="ooo.Generate")
    parser.add_argument("--force", action="store_true", help="regenerate even on a cache hit")
    args = parser.parse_args()
    generate(args.directory, args.generator, force=args.force)


if __name__ == "__main__":
    main()
